            ]
        }

        return critical.get(self.system, [])

    def load_baseline(self):
        """Load integrity baseline"""
        if os.path.exists(self.baseline_file):
            try:
                with open(self.baseline_file, 'r') as f:
                    return json.load(f)
            except Exception as e:
                self.logger.error(f"Error loading baseline: {e}")
                return {'files': {}, 'created': None}

        return {'files': {}, 'created': None}

    def save_baseline(self):
        """Save integrity baseline"""
        try:
            with open(self.baseline_file, 'w') as f:
                json.dump(self.baseline, f, indent=2)
            self.logger.info(f"Baseline saved to {self.baseline_file}")
            return True
        except Exception as e:
            self.logger.error(f"Error saving baseline: {e}")
            return False

    def calculate_file_hash(self, filepath, hash_type='sha256'):
        """Calculate file hash"""
        try:
            hash_func = hashlib.new(hash_type)
            with open(filepath, 'rb') as f:
                for chunk in iter(lambda: f.read(8192), b''):
                    hash_func.update(chunk)
            return hash_func.hexdigest()
        except Exception as e:
            self.logger.error(f"Error hashing {filepath}: {e}")
            return None

    def get_file_metadata(self, filepath):
        """Get file metadata"""
        try:
            stat = os.stat(filepath)
            return {
                'size': stat.st_size,
                'modified': stat.st_mtime,
                'permissions': oct(stat.st_mode)[-3:],
                'owner': stat.st_uid,
                'group': stat.st_gid
            }
        except Exception as e:
            self.logger.error(f"Error getting metadata for {filepath}: {e}")
            return None

    def create_baseline(self):
        """Create new integrity baseline"""
        print(f"\n{Fore.CYAN}[*] Creating integrity baseline...{Style.RESET_ALL}")

        baseline_data = {
