            'system': platform.platform(),
            'files': {}
        }

        # Baseline critical files
        for filepath in self.critical_files:
            if os.path.exists(filepath) and not os.path.islink(filepath):
                if os.path.isfile(filepath):
                    print(f"  Processing: {filepath}")
                    file_hash = self.calculate_file_hash(filepath)
                    metadata = self.get_file_metadata(filepath)

                    if file_hash and metadata:
                        baseline_data['files'][filepath] = {
                            'hash': file_hash,
                            'metadata': metadata
                        }
                        self.stats['files_checked'] += 1
                elif os.path.isdir(filepath):
                    # Walk directory
                    for root, dirs, files in os.walk(filepath):
                        for file in files:
                            fullpath = os.path.join(root, file)
                            if os.path.isfile(fullpath) and not os.path.islink(fullpath):
                                print(f"  Processing: {fullpath}")
                                file_hash = self.calculate_file_hash(fullpath)
                                metadata = self.get_file_metadata(fullpath)

                                if file_hash and metadata:
                                    baseline_data['files'][fullpath] = {
                                        'hash': file_hash,
                                        'metadata': metadata
                                    }
                                    self.stats['files_checked'] += 1

        self.baseline = baseline_data
        self.save_baseline()

        print(f"\n{Fore.GREEN}[✓] Baseline created with {len(baseline_data['files'])} files{Style.RESET_ALL}")
        return baseline_data

    def verify_file_integrity(self, filepath):
        """Verify single file integrity"""
        if filepath not in self.baseline['files']:
            return {'status': 'not_in_baseline', 'file': filepath}

        baseline = self.baseline['files'][filepath]

        if not os.path.exists(filepath):
            return {'status': 'missing', 'file': filepath}

        # Check hash
        current_hash = self.calculate_file_hash(filepath)
        if current_hash != baseline['hash']:
            return {
                'status': 'modified',
                'file': filepath,
                'expected_hash': baseline['hash'],
                'current_hash': current_hash,
                'type': 'hash_mismatch'
            }

        # Check metadata
        current_meta = self.get_file_metadata(filepath)
        if current_meta:
            changes = []
            if current_meta['size'] != baseline['metadata']['size']:
                changes.append('size')
            if current_meta['permissions'] != baseline['metadata']['permissions']:
                changes.append('permissions')
            if current_meta['modified'] != baseline['metadata']['modified']:
                changes.append('modification_time')

            if changes:
                return {
                    'status': 'modified',
                    'file': filepath,
                    'changes': changes,
                    'type': 'metadata_changed'
                }

        return {'status': 'ok', 'file': filepath}

    def verify_system_integrity(self):
        """Verify entire system integrity"""
        print(f"\n{Fore.CYAN}[*] Verifying system integrity...{Style.RESET_ALL}")

        if not self.baseline['files']:
            print(f"{Fore.RED}[!] No baseline found. Create baseline first.{Style.RESET_ALL}")
            return False

        # Check all files in baseline
        for filepath in self.baseline['files']:
            result = self.verify_file_integrity(filepath)
            self.stats['files_checked'] += 1

            if result['status'] == 'modified':
                self.stats['files_modified'] += 1
                self.violations.append(result)
                print(f"{Fore.RED}  [!] MODIFIED: {filepath}{Style.RESET_ALL}")
                if 'type' in result:
                    print(f"{Fore.RED}      Reason: {result['type']}{Style.RESET_ALL}")

            elif result['status'] == 'missing':
                self.stats['files_missing'] += 1
                self.violations.append(result)
                print(f"{Fore.RED}  [!] MISSING: {filepath}{Style.RESET_ALL}")

        # Check for new files in critical locations
        if self.verify_all:
            print(f"\n{Fore.CYAN}[*] Checking for new files...{Style.RESET_ALL}")
