        print(f"\n{Fore.GREEN}[✓] Report saved to {report_file}{Style.RESET_ALL}")

        return report_file

    def calculate_integrity_score(self):
        """Calculate integrity score (0-100%)"""
        total_files = len(self.baseline['files'])
        if total_files == 0:
            return 0

        violations_weight = {
            'modified': 1.0,
            'missing': 1.0,
            'new': 0.5,
            'permission_changes': 0.3
        }

        total_penalty = 0
        for violation in self.violations:
            if isinstance(violation, dict):
                status = violation.get('status', '')
                total_penalty += violations_weight.get(status, 0.5)

        score = max(0, 100 - (total_penalty / total_files * 100))
        return score

def main():
    parser = argparse.ArgumentParser(description='System Integrity Checker')
    parser.add_argument('--create-baseline', action='store_true', help='Create new baseline')
    parser.add_argument('--check', action='store_true', help='Run integrity check')
    parser.add_argument('--verify-all', action='store_true', help='Check all files (slow)')
    parser.add_argument('--baseline', default='integrity_baseline.json', help='Baseline file')

    args = parser.parse_args()

    checker = IntegrityChecker(
        baseline_file=args.baseline,
        verify_all=args.verify_all
    )

    if args.create_baseline:
        checker.create_baseline()
    elif args.check:
        checker.run_integrity_check()
    else:
        print("Use --create-baseline or --check")

if __name__ == "__main__":
    main()

