    def _signature_sets(self):
        """Split configured signatures into whole-name matches. Short or generic fragments
        (for example 'TDL' or 'Panda') are ignored: as substrings they match harmless files
        such as libltdl and produced false 'confirmed' detections."""
        file_names, process_names = set(), set()
        for rootkit, signatures in self.signatures.get('known_rootkits', {}).items():
            for sig in signatures:
                low = sig.lower()
                if re.search(r'\.(sys|dll|ko|exe)$', low):
                    file_names.add(low)
                elif len(low) >= 6 and re.fullmatch(r'[a-z0-9_.+-]+', low):
                    process_names.add(low)
        if self.system != 'Windows':
            file_names |= {n for n in self.LINUX_ROOTKIT_NAMES}
            process_names |= {n for n in self.LINUX_ROOTKIT_NAMES}
        return file_names, process_names

    def signature_scan(self):
        """Look for processes and files whose NAME exactly matches a known rootkit.
        A name match is only an indicator, so confidence is MEDIUM; confirm with content or hash checks."""
        findings = []
        file_names, process_names = self._signature_sets()

        for proc in psutil.process_iter(['pid', 'name', 'exe']):
            try:
                proc_name = (proc.info['name'] or '').lower()
                exe_base = os.path.basename(proc.info['exe'] or '').lower()
                for candidate in {proc_name, exe_base}:
                    if candidate and candidate in process_names | file_names:
                        findings.append({
                            'type': 'process_signature', 'rootkit': candidate,
                            'process': proc.info['name'], 'pid': proc.info['pid'],
                            'signature': candidate, 'confidence': 'MEDIUM',
                        })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        if self.system == 'Windows':
            system_dirs = ['C:\\Windows\\System32\\drivers\\']
        else:
            system_dirs = ['/lib/modules/', '/usr/lib/modules/']

        seen_dirs = set()
        for directory in system_dirs:
            real = os.path.realpath(directory)           # /lib is often a symlink to /usr/lib
            if not os.path.isdir(real) or real in seen_dirs:
                continue
            seen_dirs.add(real)
            for root, _dirs, files in os.walk(real):
                for name in files:
                    base = re.sub(r'\.(ko|sys)(\.(gz|xz|zst))?$', '', name.lower())
                    if name.lower() in file_names or base in file_names or base in self.LINUX_ROOTKIT_NAMES:
                        findings.append({
                            'type': 'file_signature', 'rootkit': base,
                            'file': os.path.join(root, name), 'signature': name,
                            'confidence': 'MEDIUM',
                        })
        return findings

