        high_count = sum(1 for f in self.findings if f[0] in high_risk_types)
        medium_count = sum(1 for f in self.findings if f[0] in medium_risk_types)

        if high_count > 0:
            return 'HIGH'
        elif medium_count > 2:
            return 'MEDIUM'
        elif medium_count > 0:
            return 'LOW'
        else:
            return 'NONE'

def main():
    parser = argparse.ArgumentParser(description='Rootkit Detector')
    parser.add_argument('--signatures', default='rootkit_signatures.json', help='Signatures file')
    parser.add_argument('--whitelist', default='rootkit_whitelist.json', help='Whitelist file')
    parser.add_argument('--log', default='rootkit_detector.log', help='Log file')

    args = parser.parse_args()

    detector = RootkitDetector(
        signatures_file=args.signatures,
        whitelist_file=args.whitelist,
        log_file=args.log
    )

    try:
        detector.run_detection()
    except KeyboardInterrupt:
        print(f"\n{Fore.YELLOW}[!] Scan interrupted{Style.RESET_ALL}")
    except Exception as e:
        print(f"{Fore.RED}[!] Error: {e}{Style.RESET_ALL}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Secure Boot Configuration
This script configures and manages Secure Boot to prevent bootkits
and low-level rootkits from infecting the system.
"""

import os
import sys
import subprocess
import argparse
import platform
import shutil
from datetime import datetime
from colorama import init, Fore, Style

init(autoreset=True)

class SecureBootManager:
    """
    Secure Boot Configuration and Management
    """

    def __init__(self):
        self.system = platform.system()
        self.secure_boot_status = self.check_secure_boot_status()

    def check_secure_boot_status(self):
        """Check if Secure Boot is enabled"""
        if self.system == 'Windows':
            return self.check_secure_boot_windows()
        elif self.system == 'Linux':
            return self.check_secure_boot_linux()
        elif self.system == 'Darwin':
            return self.check_secure_boot_macos()
        else:
            return {'enabled': False, 'reason': 'Unsupported OS'}

    def check_secure_boot_windows(self):
        """Check Secure Boot status on Windows"""
        status = {'enabled': False, 'details': {}}

        try:
            # Method 1: Check using Confirm-SecureBootUEFI
            result = subprocess.run(
                ['powershell', '-Command', 'Confirm-SecureBootUEFI'],
                capture_output=True, text=True
            )

            if 'True' in result.stdout:
                status['enabled'] = True
                status['details']['method'] = 'Confirm-SecureBootUEFI'

            # Method 2: Check using bcdedit
            result = subprocess.run(
                ['bcdedit', '/enum', '{current}'],
                capture_output=True, text=True
            )

            if 'secureboot' in result.stdout.lower():
                status['details']['bcdedit'] = 'SecureBoot flag present'

            # Method 3: Check using msinfo32
            result = subprocess.run(
                ['powershell', '-Command', 
                 'Get-WmiObject -Class Win32_ComputerSystem | Select-Object -ExpandProperty SecureBootState'],
                capture_output=True, text=True
            )

            if '1' in result.stdout or 'True' in result.stdout:
                status['enabled'] = True
                status['details']['wmi'] = 'SecureBootState = 1'

        except Exception as e:
            status['error'] = str(e)

        return status

    def check_secure_boot_linux(self):
        """Check Secure Boot status on Linux"""
        status = {'enabled': False, 'details': {}}

        try:
            # Check /sys/firmware/efi/efivars
            if os.path.exists('/sys/firmware/efi'):
                status['details']['efi'] = 'UEFI detected'

                # Check SecureBoot variable
                secureboot_path = '/sys/firmware/efi/efivars/SecureBoot-*'
                import glob
                files = glob.glob(secureboot_path)

                for file in files:
                    try:
                        with open(file, 'rb') as f:
                            data = f.read()
                            if len(data) > 0 and data[-1] == 1:
                                status['enabled'] = True
                                status['details']['secureboot_var'] = 'SecureBoot enabled'
                    except:
                        pass

            # Check using mokutil
            if shutil.which('mokutil'):
                result = subprocess.run(
                    ['mokutil', '--sb-state'],
                    capture_output=True, text=True
                )

                if 'enabled' in result.stdout.lower():
                    status['enabled'] = True
                    status['details']['mokutil'] = result.stdout.strip()

        except Exception as e:
            status['error'] = str(e)

        return status

    def check_secure_boot_macos(self):
        """Check Secure Boot status on macOS"""
        status = {'enabled': False, 'details': {}}

        try:
            # Check using csrutil
            result = subprocess.run(
                ['csrutil', 'status'],
                capture_output=True, text=True
            )

            if 'enabled' in result.stdout.lower():
                status['enabled'] = True
                status['details']['csrutil'] = result.stdout.strip()

            # Check boot security
            result = subprocess.run(
                ['nvram', '-p'],
                capture_output=True, text=True
            )

            if 'security-mode' in result.stdout:
                status['details']['nvram'] = 'Security mode configured'

        except Exception as e:
            status['error'] = str(e)

        return status

    def enable_secure_boot_windows(self):
        """Guide user to enable Secure Boot on Windows"""
        print(f"\n{Fore.CYAN}[*] Instructions to enable Secure Boot on Windows:{Style.RESET_ALL}")
        print(f"""
{Fore.YELLOW}1. Restart your computer
2. Enter UEFI/BIOS setup (usually F2, F10, Del during boot)
3. Navigate to Boot or Security settings
4. Find Secure Boot option
5. Set Secure Boot to Enabled
6. Save changes and exit

{Fore.CYAN}Alternative: Use Windows PowerShell as Administrator:{Style.RESET_ALL}
   # Check if Secure Boot is supported
   Get-WmiObject -Class Win32_ComputerSystem | Select-Object -ExpandProperty SecureBootState

   # Convert to UEFI (if not already)
   mbr2gpt /convert /allowFullOS

   # Enable Secure Boot via UEFI firmware settings
   shutdown /r /fw /t 0
        """)

    def enable_secure_boot_linux(self):
        """Guide user to enable Secure Boot on Linux"""
        print(f"\n{Fore.CYAN}[*] Instructions to enable Secure Boot on Linux:{Style.RESET_ALL}")
        print(f"""
{Fore.YELLOW}1. Restart your computer
2. Enter UEFI/BIOS setup (usually F2, F10, Del during boot)
3. Navigate to Boot or Security settings
4. Find Secure Boot option
5. Set Secure Boot to Enabled
6. Save changes and exit

{Fore.CYAN}Using mokutil (if available):{Style.RESET_ALL}
   # Check current status
   sudo mokutil --sb-state

   # Enable Secure Boot (requires reboot)
   sudo mokutil --enable-validation

{Fore.CYAN}Signing kernels for Secure Boot:{Style.RESET_ALL}
   # Install signing tools
   sudo apt-get install shim-signed mokutil

   # Sign a kernel module
   sudo kmodsign sha512 /var/lib/shim-signed/mok/MOK.priv /var/lib/shim-signed/mok/MOK.der module.ko
        """)

    def enable_secure_boot_macos(self):
        """Guide user to enable Secure Boot on macOS"""
        print(f"\n{Fore.CYAN}[*] Instructions to enable Secure Boot on macOS:{Style.RESET_ALL}")
        print(f"""
{Fore.YELLOW}1. Restart your Mac and hold Command+R for Recovery Mode
2. Open Terminal from Utilities menu
3. Check current status:
   csrutil status
4. Enable System Integrity Protection:
   csrutil enable
5. Restart your Mac
6. Go to System Settings → Privacy & Security
7. Under Security, select "Full Security"

{Fore.CYAN}For Apple Silicon Macs:{Style.RESET_ALL}
   Secure Boot is automatically enabled and managed by:
   - Hardware root of trust
   - Signed operating system
   - Verified boot chain
        """)

    def verify_boot_integrity(self):
        """Verify boot process integrity"""
        print(f"\n{Fore.CYAN}[*] Verifying boot integrity...{Style.RESET_ALL}")

        findings = []

        if self.system == 'Windows':
            # Check BCD configuration
            result = subprocess.run(['bcdedit', '/enum'], capture_output=True, text=True)
            bcd_output = result.stdout

            # Check for boot configuration issues
            if 'bootstatuspolicy' in bcd_output:
                findings.append(('bootstatuspolicy', bcd_output))

            # Check for Windows Boot Manager integrity
            if os.path.exists('C:\\Windows\\Boot\\EFI\\bootmgfw.efi'):
                findings.append(('bootmgfw_exists', 'Windows Boot Manager found'))

        elif self.system == 'Linux':
            # Check GRUB configuration
            if os.path.exists('/boot/grub/grub.cfg'):
                with open('/boot/grub/grub.cfg', 'r') as f:
                    grub_cfg = f.read()
                    if 'check_signatures' in grub_cfg:
                        findings.append(('grub_signatures', 'GRUB signature checking enabled'))

            # Check for UEFI boot entries
            if os.path.exists('/sys/firmware/efi/efivars'):
                findings.append(('uefi_mode', 'System booting in UEFI mode'))

        for finding in findings:
            print(f"{Fore.GREEN}  [✓] {finding[1]}{Style.RESET_ALL}")

        return findings

    def configure_boot_security(self):
        """Configure additional boot security measures"""
        print(f"\n{Fore.CYAN}[*] Configuring boot security...{Style.RESET_ALL}")

        if self.system == 'Windows':
            # Set boot configuration
            commands = [
                # Enable early launch anti-malware
                ['bcdedit', '/set', '{current}', 'bootstatuspolicy', 'IgnoreAllFailures'],
                ['bcdedit', '/set', '{current}', 'recoveryenabled', 'No'],

                # Configure boot logging
                ['bcdedit', '/set', '{current}', 'bootlog', 'Yes'],

                # Set boot options
                ['bcdedit', '/set', '{current}', 'sos', 'Yes'],
            ]

            for cmd in commands:
                try:
                    subprocess.run(cmd, check=True, capture_output=True)
                    print(f"{Fore.GREEN}  [✓] {' '.join(cmd)}{Style.RESET_ALL}")
                except Exception as e:
                    print(f"{Fore.RED}  [✗] {' '.join(cmd)}: {e}{Style.RESET_ALL}")

        elif self.system == 'Linux':
            # Configure GRUB security
            grub_configs = [
                'GRUB_ENABLE_BLSCFG=true',
                'GRUB_CMDLINE_LINUX_DEFAULT="quiet splash"',
                'GRUB_DISABLE_OS_PROBER=false',
                'GRUB_TIMEOUT=5',
                'GRUB_DISTRIBUTOR=`lsb_release -i -s 2> /dev/null || echo Debian`',
                'GRUB_GFXMODE=auto'
            ]

            grub_file = '/etc/default/grub'
            if os.path.exists(grub_file):
                with open(grub_file, 'r') as f:
                    current_config = f.read()

                # Add missing security options
                security_options = [
                    'GRUB_VERIFY_SIGNATURES=enabled',
                    'GRUB_ENABLE_CRYPTODISK=y'
                ]

                for opt in security_options:
                    if opt not in current_config:
                        with open(grub_file, 'a') as f:
                            f.write(f'\n{opt}\n')
                        print(f"{Fore.GREEN}  [✓] Added {opt}{Style.RESET_ALL}")

                # Update GRUB
                subprocess.run(['update-grub'], check=True)
                print(f"{Fore.GREEN}  [✓] GRUB configuration updated{Style.RESET_ALL}")

    def generate_security_report(self):
        """Generate boot security report"""
        report = {
            'timestamp': datetime.now().isoformat(),
            'system': platform.platform(),
            'secure_boot': self.secure_boot_status,
            'recommendations': self.get_recommendations()
        }

        report_file = f"secure_boot_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
        with open(report_file, 'w') as f:
            import json
            json.dump(report, f, indent=2)

        print(f"\n{Fore.GREEN}[✓] Report saved to {report_file}{Style.RESET_ALL}")

        return report_file

    def get_recommendations(self):
        """Get security recommendations"""
        recommendations = []

        if not self.secure_boot_status.get('enabled', False):
            recommendations.append({
                'priority': 'HIGH',
                'action': 'Enable Secure Boot',
                'reason': 'Prevents bootkits and rootkits from loading before OS'
            })

        if self.system == 'Windows':
            recommendations.extend([
                {
                    'priority': 'MEDIUM',
                    'action': 'Enable BitLocker',
                    'reason': 'Protects against offline attacks'
                },
                {
                    'priority': 'MEDIUM',
                    'action': 'Configure Windows Defender',
                    'reason': 'Early launch anti-malware protection'
                }
            ])

        elif self.system == 'Linux':
            recommendations.extend([
                {
                    'priority': 'MEDIUM',
                    'action': 'Enable LUKS disk encryption',
                    'reason': 'Protects against boot tampering'
                },
                {
                    'priority': 'HIGH',
                    'action': 'Sign kernel modules',
                    'reason': 'Prevents unauthorized kernel modules'
                }
            ])

        return recommendations

    def show_status(self):
        """Show Secure Boot status"""
        print(f"\n{Fore.CYAN}{'='*60}{Style.RESET_ALL}")
        print(f"{Fore.CYAN}🔒 SECURE BOOT STATUS{Style.RESET_ALL}")
        print(f"{Fore.CYAN}{'='*60}{Style.RESET_ALL}")

        if self.secure_boot_status.get('enabled', False):
            print(f"{Fore.GREEN}  [✓] Secure Boot is ENABLED{Style.RESET_ALL}")
        else:
            print(f"{Fore.RED}  [✗] Secure Boot is DISABLED{Style.RESET_ALL}")

        print(f"\n{Fore.CYAN}Details:{Style.RESET_ALL}")
        for key, value in self.secure_boot_status.get('details', {}).items():
            print(f"  {key}: {value}")

        if 'error' in self.secure_boot_status:
            print(f"{Fore.RED}  Error: {self.secure_boot_status['error']}{Style.RESET_ALL}")

        # Show recommendations
        recommendations = self.get_recommendations()
        if recommendations:
            print(f"\n{Fore.YELLOW}Recommendations:{Style.RESET_ALL}")
            for rec in recommendations:
                priority_color = Fore.RED if rec['priority'] == 'HIGH' else Fore.YELLOW
                print(f"  {priority_color}[{rec['priority']}]{Style.RESET_ALL} {rec['action']}")
                print(f"     {rec['reason']}")

        print(f"\n{Fore.CYAN}{'='*60}{Style.RESET_ALL}")

def main():
    parser = argparse.ArgumentParser(description='Secure Boot Manager')
    parser.add_argument('--status', action='store_true', help='Show Secure Boot status')
    parser.add_argument('--enable', action='store_true', help='Show instructions to enable Secure Boot')
    parser.add_argument('--verify', action='store_true', help='Verify boot integrity')
    parser.add_argument('--configure', action='store_true', help='Configure boot security')
    parser.add_argument('--report', action='store_true', help='Generate security report')

    args = parser.parse_args()

    manager = SecureBootManager()

    if args.status:
        manager.show_status()

    if args.enable:
        if manager.system == 'Windows':
            manager.enable_secure_boot_windows()
        elif manager.system == 'Linux':
            manager.enable_secure_boot_linux()
        elif manager.system == 'Darwin':
            manager.enable_secure_boot_macos()

    if args.verify:
        manager.verify_boot_integrity()

    if args.configure:
        manager.configure_boot_security()

    if args.report:
        manager.generate_security_report()

    if not any([args.status, args.enable, args.verify, args.configure, args.report]):
        manager.show_status()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Trojan Scanner
Location: 03-malware-analysis/trojans/detection/trojan_scanner.py

This script scans for trojan infections using signature-based detection,
heuristic analysis, and behavioral indicators.
"""

import os
import sys
import hashlib
import json
import time
import argparse
import psutil
import re
import shutil
import subprocess
from pathlib import Path
from datetime import datetime, timedelta
from collections import defaultdict
import pefile
import requests
from colorama import init, Fore, Style

init(autoreset=True)

class TrojanScanner:
    """
    Trojan Scanner with multiple detection methods
    """

    def __init__(self, scan_paths=None, signatures_file="trojan_signatures.json",
                 quarantine_dir="/quarantine", use_virustotal=False, vt_api_key=None):
        """
        Initialize Trojan Scanner

        Args:
            scan_paths: List of paths to scan
            signatures_file: File containing trojan signatures
            quarantine_dir: Directory for quarantined files
            use_virustotal: Enable VirusTotal API checking
            vt_api_key: VirusTotal API key
        """
        self.scan_paths = scan_paths or [
            "C:\\" if os.name == 'nt' else "/",
            str(Path.home())
        ]
        self.signatures_file = signatures_file
        self.quarantine_dir = quarantine_dir
        self.use_virustotal = use_virustotal
        self.vt_api_key = vt_api_key

        # Create quarantine directory
        os.makedirs(quarantine_dir, exist_ok=True)

        # Signatures storage
        self.signatures = self.load_signatures()

        # Known trojan indicators
        self.trojan_indicators = {
            'file_names': [
                'svchost.exe', 'explorer.exe', 'iexplore.exe', 'winlogon.exe',
                'services.exe', 'lsass.exe', 'csrss.exe', 'smss.exe'
            ],
            'suspicious_strings': [
                'mIRC', 'P2P', 'backdoor', 'rat', 'remote admin',
                'keylogger', 'password stealer', 'inject', 'hook',
                'CreateRemoteThread', 'WriteProcessMemory', 'VirtualAllocEx'
            ],
            'registry_keys': [
                r'SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
                r'SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
                r'SOFTWARE\Microsoft\Windows\CurrentVersion\RunServices',
                r'SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Run'
            ],
            'suspicious_ports': [4444, 1337, 6667, 8080, 8443, 31337, 12345, 27374],
            'suspicious_domains': [
                'no-ip.org', 'dyndns.org', 'servehttp.com', 'redirectme.net',
                'hopto.org', 'serveftp.net', 'ddns.net', 'zapto.org'
            ]
        }

        # Statistics
        self.stats = {
            'files_scanned': 0,
            'suspicious_files': 0,
            'infected_files': 0,
            'quarantined_files': 0,
            'errors': 0,
            'start_time': time.time()
        }

        # Scan results
        self.results = {
            'scan_id': datetime.now().strftime('%Y%m%d_%H%M%S'),
            'timestamp': datetime.now().isoformat(),
            'findings': [],
            'statistics': self.stats
        }

    def load_signatures(self):
        """Load trojan signatures from file"""
        if os.path.exists(self.signatures_file):
            try:
                with open(self.signatures_file, 'r') as f:
                    return json.load(f)
            except Exception as e:
                print(f"{Fore.YELLOW}[!] Error loading signatures: {e}{Style.RESET_ALL}")

        # Default signatures
        return {
            'hashes': {},
            'strings': [],
            'patterns': [],
            'yara_rules': []
        }

    def save_signatures(self):
        """Save signatures to file"""
        try:
            with open(self.signatures_file, 'w') as f:
                json.dump(self.signatures, f, indent=2)
            print(f"{Fore.GREEN}[✓] Signatures saved to {self.signatures_file}{Style.RESET_ALL}")
        except Exception as e:
            print(f"{Fore.RED}[✗] Error saving signatures: {e}{Style.RESET_ALL}")

    def calculate_file_hash(self, filepath, hash_type='sha256'):
        """Calculate file hash"""
        try:
            hash_func = hashlib.new(hash_type)
            with open(filepath, 'rb') as f:
                for chunk in iter(lambda: f.read(8192), b''):
                    hash_func.update(chunk)
            return hash_func.hexdigest()
        except Exception:
            return None

    def check_virustotal(self, filepath):
        """Check file against VirusTotal API"""
        if not self.use_virustotal or not self.vt_api_key:
            return None

        try:
            file_hash = self.calculate_file_hash(filepath)
            if not file_hash:
                return None

            url = f"https://www.virustotal.com/api/v3/files/{file_hash}"
            headers = {'x-apikey': self.vt_api_key}

            response = requests.get(url, headers=headers, timeout=10)
            if response.status_code == 200:
                data = response.json()
                stats = data.get('data', {}).get('attributes', {}).get('last_analysis_stats', {})
                return {
                    'malicious': stats.get('malicious', 0),
                    'suspicious': stats.get('suspicious', 0),
                    'undetected': stats.get('undetected', 0),
                    'total': sum(stats.values())
                }
            elif response.status_code == 404:
                return {'not_found': True}

        except Exception as e:
            print(f"{Fore.YELLOW}[!] VirusTotal API error: {e}{Style.RESET_ALL}")

        return None

    def check_pe_file(self, filepath):
        """Analyze PE file for suspicious characteristics"""
        try:
            pe = pefile.PE(filepath)
            suspicious = []

            # Check for suspicious sections
            for section in pe.sections:
                name = section.Name.decode('utf-8', errors='ignore').strip('\x00')
                characteristics = section.Characteristics

                # Suspicious section names
                if name in ['.upx', '.packed', '.themida', '.vmp']:
                    suspicious.append(f"Packed section: {name}")

                # Check for executable and writable sections
                if characteristics & 0x80000000 and characteristics & 0x20000000:  # MEM_WRITE and MEM_EXECUTE
                    suspicious.append(f"Executable and writable section: {name}")

            # Check imports for suspicious APIs
            suspicious_apis = [
                'CreateRemoteThread', 'WriteProcessMemory', 'ReadProcessMemory',
                'VirtualAllocEx', 'SetWindowsHookEx', 'GetAsyncKeyState',
                'socket', 'connect', 'send', 'recv', 'URLDownloadToFile'
            ]

            if hasattr(pe, 'DIRECTORY_ENTRY_IMPORT'):
                for entry in pe.DIRECTORY_ENTRY_IMPORT:
                    for imp in entry.imports:
                        if imp.name and imp.name.decode('utf-8', errors='ignore') in suspicious_apis:
                            suspicious.append(f"Suspicious API: {imp.name.decode('utf-8', errors='ignore')}")

            # Check for suspicious resources
            if hasattr(pe, 'DIRECTORY_ENTRY_RESOURCE'):
                for resource_type in pe.DIRECTORY_ENTRY_RESOURCE.entries:
                    if resource_type.name is not None:
                        if str(resource_type.name).find('RT_RCDATA') >= 0:
                            suspicious.append("Contains embedded resources (possible payload)")

            # Check for digital signature
            if not hasattr(pe, 'DIRECTORY_ENTRY_SECURITY'):
                suspicious.append("No digital signature")

            # Check entry point
            if pe.OPTIONAL_HEADER.AddressOfEntryPoint in [section.VirtualAddress for section in pe.sections]:
                suspicious.append("Entry point in suspicious location")

            return suspicious

        except Exception as e:
            return [f"PE analysis error: {e}"]

    def check_strings(self, filepath):
        """Extract and analyze strings from file"""
        suspicious_strings = []

        try:
            # Extract strings using strings command
            if os.name == 'posix':
                result = subprocess.run(['strings', filepath], capture_output=True, text=True, timeout=10)
                strings = result.stdout.split('\n')
            else:
                # Simple string extraction for Windows
                with open(filepath, 'rb') as f:
                    data = f.read()
                    strings = []
                    current = []
                    for b in data:
                        if 32 <= b <= 126:  # Printable ASCII
                            current.append(chr(b))
                        elif current:
                            if len(current) > 4:  # Minimum string length
                                strings.append(''.join(current))
                            current = []

            # Check for suspicious strings
            for string in strings[:1000]:  # Limit for performance
                string_lower = string.lower()

                # Check against known suspicious strings
                for indicator in self.trojan_indicators['suspicious_strings']:
                    if indicator.lower() in string_lower:
                        suspicious_strings.append(string)
                        break

                # Check for URLs/IPs
                if re.match(r'https?://', string_lower):
                    suspicious_strings.append(f"URL: {string}")

                if re.match(r'\d+\.\d+\.\d+\.\d+', string):
                    suspicious_strings.append(f"IP: {string}")

                # Check for dynamic DNS domains
                for domain in self.trojan_indicators['suspicious_domains']:
                    if domain in string_lower:
                        suspicious_strings.append(f"Dynamic DNS: {string}")

        except Exception as e:
            suspicious_strings.append(f"String extraction error: {e}")

        return suspicious_strings[:20]  # Return top 20

    def check_entropy(self, filepath):
        """Calculate file entropy (high entropy indicates packed/encrypted)"""
        try:
            with open(filepath, 'rb') as f:
                data = f.read()

                if not data:
                    return 0

                entropy = 0
                for x in range(256):
                    p_x = data.count(x) / len(data)
                    if p_x > 0:
                        entropy += -p_x * (p_x.bit_length())

                return entropy / 8  # Normalize to 0-1

        except Exception:
            return 0

    def signature_match(self, filepath):
        """Check against known trojan signatures"""
        file_hash = self.calculate_file_hash(filepath)
        if file_hash and file_hash in self.signatures.get('hashes', {}):
            return self.signatures['hashes'][file_hash]
        return None

    def scan_file(self, filepath):
        """Scan individual file"""
        self.stats['files_scanned'] += 1

        findings = {
            'file': filepath,
            'size': os.path.getsize(filepath) if os.path.exists(filepath) else 0,
            'modified': datetime.fromtimestamp(os.path.getmtime(filepath)).isoformat() if os.path.exists(filepath) else None,
            'indicators': []
        }

        # Skip if too large (>100MB)
        if findings['size'] > 100 * 1024 * 1024:
            return None

        # 1. Signature-based detection
        signature = self.signature_match(filepath)
        if signature:
            findings['indicators'].append({
                'type': 'signature',
                'severity': 'HIGH',
                'description': f"Matches known trojan: {signature.get('name', 'Unknown')}"
            })
            self.stats['infected_files'] += 1

        # 2. Check file extension
        ext = os.path.splitext(filepath)[1].lower()
        if ext in ['.exe', '.dll', '.scr', '.bat', '.cmd', '.vbs', '.ps1']:
            # Suspicious file names
            filename = os.path.basename(filepath).lower()
            for suspicious_name in self.trojan_indicators['file_names']:
                if suspicious_name in filename and filename != suspicious_name:
                    findings['indicators'].append({
                        'type': 'masquerading',
                        'severity': 'MEDIUM',
                        'description': f"File masquerading as {suspicious_name}"
                    })

        # 3. PE analysis for executables
        if ext in ['.exe', '.dll', '.scr']:
            pe_issues = self.check_pe_file(filepath)
            for issue in pe_issues:
                findings['indicators'].append({
                    'type': 'pe_analysis',
                    'severity': 'MEDIUM',
                    'description': issue
                })

        # 4. String analysis
        suspicious_strings = self.check_strings(filepath)
        if suspicious_strings:
            findings['indicators'].append({
                'type': 'strings',
                'severity': 'LOW',
                'description': f"Suspicious strings found: {', '.join(suspicious_strings[:3])}"
            })

        # 5. Entropy check
        entropy = self.check_entropy(filepath)
        if entropy > 0.7:
            findings['indicators'].append({
                'type': 'entropy',
                'severity': 'MEDIUM',
                'description': f"High entropy ({entropy:.2f}) - possible packed/encrypted"
            })

        # 6. VirusTotal check
        if self.use_virustotal:
            vt_result = self.check_virustotal(filepath)
            if vt_result:
                if vt_result.get('malicious', 0) > 0:
                    findings['indicators'].append({
                        'type': 'virustotal',
                        'severity': 'HIGH',
                        'description': f"VirusTotal: {vt_result['malicious']}/{vt_result['total']} detections"
                    })
                    self.stats['infected_files'] += 1
                elif vt_result.get('not_found'):
                    findings['indicators'].append({
                        'type': 'virustotal',
                        'severity': 'LOW',
                        'description': "Not found in VirusTotal (possibly new malware)"
                    })

        # Determine overall risk
        if findings['indicators']:
            self.stats['suspicious_files'] += 1

            # Calculate risk score
            risk_score = 0
            for indicator in findings['indicators']:
                if indicator['severity'] == 'HIGH':
                    risk_score += 3
                elif indicator['severity'] == 'MEDIUM':
                    risk_score += 2
                else:
                    risk_score += 1

            findings['risk_score'] = risk_score
            findings['risk_level'] = 'HIGH' if risk_score > 5 else 'MEDIUM' if risk_score > 2 else 'LOW'

            return findings

        return None

    def scan_directory(self, directory):
        """Scan directory recursively"""
        print(f"\n{Fore.CYAN}[*] Scanning directory: {directory}{Style.RESET_ALL}")

        for root, dirs, files in os.walk(directory):
            # Skip system directories for performance
            if any(skip in root.lower() for skip in ['windows\\system32\\config', '$recycle.bin', 'system volume information']):
                continue

            for file in files:
                filepath = os.path.join(root, file)

                try:
                    findings = self.scan_file(filepath)

                    if findings:
                        self.results['findings'].append(findings)

                        # Print finding
                        risk_color = Fore.RED if findings['risk_level'] == 'HIGH' else Fore.YELLOW if findings['risk_level'] == 'MEDIUM' else Fore.CYAN
                        print(f"{risk_color}[!] {findings['risk_level']} risk: {filepath}{Style.RESET_ALL}")
                        for indicator in findings['indicators']:
                            print(f"      - [{indicator['severity']}] {indicator['description']}")

                    # Progress indicator
                    if self.stats['files_scanned'] % 100 == 0:
                        print(f"{Fore.CYAN}  [*] Scanned {self.stats['files_scanned']} files...{Style.RESET_ALL}")

                except Exception as e:
                    self.stats['errors'] += 1
                    print(f"{Fore.RED}[!] Error scanning {filepath}: {e}{Style.RESET_ALL}")

    def scan_processes(self):
        """Scan running processes for trojans"""
        print(f"\n{Fore.CYAN}[*] Scanning running processes...{Style.RESET_ALL}")

        for proc in psutil.process_iter(['pid', 'name', 'exe', 'cmdline']):
            try:
                proc_info = proc.info

                if proc_info['exe'] and os.path.exists(proc_info['exe']):
                    findings = self.scan_file(proc_info['exe'])

                    if findings:
                        findings['process'] = {
                            'pid': proc_info['pid'],
                            'name': proc_info['name'],
                            'cmdline': proc_info['cmdline']
                        }
                        self.results['findings'].append(findings)

                        print(f"{Fore.RED}[!] Suspicious process: {proc_info['name']} (PID: {proc_info['pid']}){Style.RESET_ALL}")

            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass

    def scan_registry(self):
        """Scan Windows registry for trojan persistence"""
        if os.name != 'nt':
            return

        print(f"\n{Fore.CYAN}[*] Scanning registry for trojan persistence...{Style.RESET_ALL}")

        import winreg

        for reg_key in self.trojan_indicators['registry_keys']:
            try:
                key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, reg_key)

                i = 0
                while True:
                    try:
                        value_name, value_data, _ = winreg.EnumValue(key, i)

                        # Check if value points to suspicious file
                        if isinstance(value_data, str) and os.path.exists(value_data):
                            findings = self.scan_file(value_data)

                            if findings:
                                findings['registry'] = {
                                    'key': reg_key,
                                    'value': value_name,
                                    'data': value_data
                                }
                                self.results['findings'].append(findings)

                                print(f"{Fore.RED}[!] Suspicious registry entry: {reg_key}\\{value_name} -> {value_data}{Style.RESET_ALL}")

                        i += 1
                    except WindowsError:
                        break

                winreg.CloseKey(key)
            except:
                pass

    def quarantine_file(self, filepath):
        """Move suspicious file to quarantine"""
        try:
            filename = os.path.basename(filepath)
            quarantine_path = os.path.join(self.quarantine_dir, f"{int(time.time())}_{filename}")

            # Copy file with metadata
            shutil.copy2(filepath, quarantine_path)

            # Add .quarantine extension
            os.rename(quarantine_path, quarantine_path + '.quarantine')

            # Delete original
            os.remove(filepath)

            self.stats['quarantined_files'] += 1
            print(f"{Fore.GREEN}[✓] Quarantined: {filepath}{Style.RESET_ALL}")

            return quarantine_path + '.quarantine'

        except Exception as e:
            print(f"{Fore.RED}[✗] Error quarantining {filepath}: {e}{Style.RESET_ALL}")
            return None

    def generate_report(self):
        """Generate scan report"""
        self.stats['duration'] = time.time() - self.stats['start_time']
        self.results['statistics'] = self.stats

        # Save report
        report_file = f"trojan_scan_{self.results['scan_id']}.json"
        with open(report_file, 'w') as f:
            json.dump(self.results, f, indent=2)

        # Print summary
        print(f"\n{Fore.CYAN}{'='*60}{Style.RESET_ALL}")
        print(f"{Fore.CYAN}📊 TROJAN SCAN SUMMARY{Style.RESET_ALL}")
        print(f"{Fore.CYAN}{'='*60}{Style.RESET_ALL}")
        print(f"  Scan ID: {self.results['scan_id']}")
        print(f"  Duration: {self.stats['duration']:.2f} seconds")
        print(f"  Files Scanned: {self.stats['files_scanned']}")
        print(f"  Suspicious Files: {self.stats['suspicious_files']}")
        print(f"  Infected Files: {self.stats['infected_files']}")
        print(f"  Quarantined Files: {self.stats['quarantined_files']}")
        print(f"  Errors: {self.stats['errors']}")
        print(f"{Fore.CYAN}{'='*60}{Style.RESET_ALL}")

        # List high risk findings
        high_risk = [f for f in self.results['findings'] if f.get('risk_level') == 'HIGH']
        if high_risk:
            print(f"\n{Fore.RED}HIGH RISK FINDINGS:{Style.RESET_ALL}")
            for finding in high_risk[:10]:
                print(f"  - {finding['file']}")

        print(f"\n{Fore.GREEN}[✓] Report saved to {report_file}{Style.RESET_ALL}")

        return report_file

    def run_scan(self, scan_processes=True, scan_registry=True, auto_quarantine=False):
        """Run complete trojan scan"""
        print(f"""
        {Fore.CYAN}╔═══════════════════════════════════════╗
        ║        Trojan Scanner v1.0           ║
        ║      FOR EDUCATIONAL USE ONLY        ║
        ╚═══════════════════════════════════════╝{Style.RESET_ALL}
        """)

        print(f"{Fore.YELLOW}[!] WARNING: This tool should only be used on systems you own{Style.RESET_ALL}")
        print(f"{Fore.YELLOW}[!] Always have proper backups before scanning{Style.RESET_ALL}\n")

        # Scan directories
        for path in self.scan_paths:
            if os.path.exists(path):
                self.scan_directory(path)

        # Scan processes
        if scan_processes:
            self.scan_processes()

        # Scan registry
        if scan_registry and os.name == 'nt':
            self.scan_registry()

        # Auto-quarantine if requested
        if auto_quarantine:
            for finding in self.results['findings']:
                if finding.get('risk_level') == 'HIGH':
                    response = input(f"\n{Fore.YELLOW}[?] Quarantine {finding['file']}? (yes/no): {Style.RESET_ALL}")
                    if response.lower() == 'yes':
                        self.quarantine_file(finding['file'])

        # Generate report
        self.generate_report()

def main():
    parser = argparse.ArgumentParser(description='Trojan Scanner')
    parser.add_argument('-p', '--paths', help='Paths to scan (comma-separated)')
    parser.add_argument('--no-processes', action='store_true', help='Skip process scanning')
    parser.add_argument('--no-registry', action='store_true', help='Skip registry scanning')
    parser.add_argument('--quarantine', action='store_true', help='Auto-quarantine high risk files')
    parser.add_argument('--virustotal', action='store_true', help='Enable VirusTotal checking')
    parser.add_argument('--vt-api-key', help='VirusTotal API key')
    parser.add_argument('--signatures', default='trojan_signatures.json', help='Signatures file')

    args = parser.parse_args()

    # Parse paths
    scan_paths = args.paths.split(',') if args.paths else None

    scanner = TrojanScanner(
        scan_paths=scan_paths,
        signatures_file=args.signatures,
        use_virustotal=args.virustotal,
        vt_api_key=args.vt_api_key
    )

    scanner.run_scan(
        scan_processes=not args.no_processes,
        scan_registry=not args.no_registry,
        auto_quarantine=args.quarantine
    )

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
USB baiting scanner
Location: 04-social-engineering/baiting/detection/usb_bait_scanner.py

Baiting leaves infected or malicious media where a curious person will plug it in. Two read-only checks:

  1. scan_directory(): inspect a mounted drive WITHOUT opening anything on it
       autorun.inf; executables and scripts (.exe .scr .bat .ps1 .vbs .js .jar .lnk .hta .msi ...);
       DOUBLE extensions such as invoice.pdf.exe; macro-enabled Office files; hidden files at the top
       level; very long names with padding spaces that hide the real extension
  2. inspect_usb_devices(): look at the USB descriptors on Linux. A "flash drive" that ALSO presents a
       HID keyboard interface is the signature of keystroke-injection devices (Rubber Ducky, BadUSB)

Never double-click files from found media. Mount it read-only (mount -o ro,noexec,nosuid,nodev) or use a
sacrificial machine. Exit codes: 0 = clean, 1 = findings, 2 = input problem.
"""

import argparse
import json
import os
import re
import sys

EXECUTABLE = {".exe", ".scr", ".com", ".bat", ".cmd", ".ps1", ".vbs", ".vbe", ".js", ".jse", ".wsf", ".jar", ".lnk",
              ".hta", ".msi", ".dll", ".sh", ".desktop", ".command", ".app", ".apk", ".reg", ".cpl"}
DOCUMENT = {".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".txt", ".jpg", ".jpeg", ".png", ".zip", ".rtf"}
MACRO = {".docm", ".xlsm", ".pptm", ".dotm", ".xlam"}
SEVERITY_ORDER = {"HIGH": 0, "MEDIUM": 1, "LOW": 2}


def scan_directory(root, max_files=20000):
    findings, count = [], 0
    root = os.path.abspath(root)
    for folder, _dirs, files in os.walk(root):
        for name in files:
            count += 1
            if count > max_files:
                findings.append({"severity": "LOW", "file": root, "issue": f"stopped after {max_files} files"})
                return findings
            path = os.path.join(folder, name)
            rel = os.path.relpath(path, root)
            lower = name.lower()
            stem, ext = os.path.splitext(lower)
            inner_ext = os.path.splitext(stem)[1]

            if lower == "autorun.inf":
                findings.append({"severity": "HIGH", "file": rel, "issue": "autorun.inf (tries to launch code when the drive is inserted)"})
            if ext in EXECUTABLE and inner_ext in DOCUMENT:
                findings.append({"severity": "HIGH", "file": rel, "issue": f"double extension '{inner_ext}{ext}': an executable disguised as a document"})
            elif ext in EXECUTABLE:
                top_level = os.path.dirname(rel) == ""
                findings.append({"severity": "HIGH" if top_level else "MEDIUM", "file": rel,
                                 "issue": f"executable or script type ({ext})" + (" in the drive root" if top_level else "")})
            if ext in MACRO:
                findings.append({"severity": "MEDIUM", "file": rel, "issue": "macro-enabled Office document"})
            if re.search(r"\s{5,}\.\w+$", name):
                findings.append({"severity": "HIGH", "file": rel, "issue": "padding spaces before the extension hide the real file type"})
            if name.startswith(".") and os.path.dirname(rel) == "" and lower not in {".ds_store", ".trashes", ".fseventsd"}:
                findings.append({"severity": "LOW", "file": rel, "issue": "hidden file in the drive root"})
    return findings


def read(path):
    try:
        return open(path).read().strip()
    except OSError:
        return ""


def inspect_usb_devices(sysfs="/sys/bus/usb/devices"):
    """Flag devices exposing more than one interface class where HID keyboard is mixed with storage."""
    findings = []
    if not os.path.isdir(sysfs):
        return findings
    devices = {}
    for entry in os.listdir(sysfs):
        device_id = entry.split(":")[0]
        iface = os.path.join(sysfs, entry)
        cls = read(os.path.join(iface, "bInterfaceClass"))
        if cls:
            proto = read(os.path.join(iface, "bInterfaceProtocol"))
            devices.setdefault(device_id, []).append((cls.lower(), proto))
    for device_id, interfaces in devices.items():
        classes = {c for c, _ in interfaces}
        keyboard = any(c == "03" and p == "01" for c, p in interfaces)
        product = read(os.path.join(sysfs, device_id, "product")) or "unknown device"
        if keyboard and "08" in classes:
            findings.append({"severity": "HIGH", "file": device_id,
                             "issue": f"'{product}' is a storage device that ALSO acts as a keyboard (keystroke-injection signature)"})
        elif keyboard and len(classes) > 1:
            findings.append({"severity": "MEDIUM", "file": device_id,
                             "issue": f"'{product}' is a keyboard with extra interfaces ({', '.join(sorted(classes))}); verify it is a genuine device"})
    return findings


def main():
    parser = argparse.ArgumentParser(description="USB baiting scanner (read-only)")
    parser.add_argument("path", nargs="?", help="mounted drive or folder to inspect")
    parser.add_argument("--check-usb", action="store_true", help="also inspect attached USB devices (Linux)")
    parser.add_argument("--sysfs", default="/sys/bus/usb/devices", help=argparse.SUPPRESS)
    parser.add_argument("-o", "--output")
    args = parser.parse_args()
    if not args.path and not args.check_usb:
        parser.error("give a path to scan and/or --check-usb")
    findings = []
    if args.path:
        if not os.path.isdir(args.path):
            print(f"[x] Not a directory: {args.path}")
            return 2
        findings += scan_directory(args.path)
    if args.check_usb:
        findings += inspect_usb_devices(args.sysfs)
    findings.sort(key=lambda f: SEVERITY_ORDER[f["severity"]])
    for f in findings:
        print(f"  [{f['severity']}] {f['file']}: {f['issue']}")
    print("[+] Nothing suspicious found. Still mount unknown media read-only." if not findings else f"[!] {len(findings)} finding(s): do NOT open files from this media")
    if args.output:
        json.dump(findings, open(args.output, "w"), indent=2)
    return 1 if [f for f in findings if f["severity"] != "LOW"] else 0


if __name__ == "__main__":
    sys.exit(main())

